const title = $json.title ?? '';
const link = $json.link ?? $json.guid ?? '';
const normalized = title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
return [{json:{...$json, title, link, item_key:`news:${normalized}`, source:'news', text:`${title} ${$json.contentSnippet ?? $json.content ?? ''}`}}];

const data = JSON.parse($json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}');
if (!data.titulo || !data.resumen) throw new Error('JSON de Gemini inválido');
return [{json:data}];
